export interface NightPipelineDependencies {
  readonly rulePlan?: RulePlan;
  world: World;
  toolGateway: ToolGateway;
  damageResolutionSystem: DamageResolutionSystem;
  events: GameEvent[];
  stageRegistry?: NightStageRegistry;
  random?: RandomSource;
}

export interface NightPipelineOptions {
  readonly lifecycleHandoff?: NightLifecycleHandoff;
  previousExile?: Readonly<ExileFeedback> | null;
  isCurrent?: () => boolean;
}
export type NightPipelineResult =
  | {
      interrupted: false;
      summary: NightSummary;
      damage: DamageResolutionResult;
      dreamFrame: DreamNightEffects;
      mistDelay?: boolean;
      demonSources?: object;
      retaliationAttacks?: readonly import("../../../core/domain/night_effects").NightRetaliationAttack[];
      /** 本族捕获的运行查询；不携带可替换 Map 或私有库存结构。 */
      blocksPassiveNightShot?: (targetId: EntityId) => boolean;
      inspectionAttacks?: readonly import("../../../core/domain/night_effects").NightInspectionAttack[];
      demonWolfSourceCurrent?: (targetId: number) => boolean;
      demonKnifeProtection?: DemonKnifeProtection;
      foxInspections?: readonly import("../../../core/domain/night_effects").NightFoxInspectionClaim[];
      deathLives: ReadonlyMap<EntityId, { life: AliveComponent; version: number | undefined }>;
    }
  | { interrupted: true };

/**
 * 夜间阶段流水线：
 * - 通过 NightStageRegistry 串行驱动夜间子阶段；
 * - 最后统一执行伤害结算并返回结果。
 * night_resolved 事件由 PhaseManager 按白天流程时序写入。
 */
export class NightPipeline {
  private readonly world: World;
  private readonly toolGateway: ToolGateway;
  private readonly damageResolutionSystem: DamageResolutionSystem;
  private readonly events: GameEvent[];
  private readonly stageRegistry: NightStageRegistry;
  private readonly random: RandomSource;
  #rulePlan?: RulePlan;

  constructor(dependencies: NightPipelineDependencies) {
    this.world = dependencies.world;
    this.toolGateway = dependencies.toolGateway;
    this.damageResolutionSystem = dependencies.damageResolutionSystem;
    this.events = dependencies.events;
    this.stageRegistry = dependencies.stageRegistry ?? getDefaultNightStageRegistry();
    this.random = dependencies.random ?? createRandom();
    this.#rulePlan = dependencies.rulePlan;
  }

  /**
   * 执行完整夜间流程并返回结算摘要与伤害结果。
   */
  async execute(
    config: ReadonlyBoardConfig,
    actionProvider: ActionProvider,
    day: number,
    options: NightPipelineOptions = {},
  ): Promise<NightPipelineResult> {
    assertNightSetupReady({ world: () => this.world });
    const isCurrent = options.isCurrent ?? (() => true);
    if (!isCurrent())
      return attachNobleNightReceiver({ interrupted: true }, createNobleNightAbortReceiver());
    const pipeline = this;
    const prepare = this.#rulePlan
      ? this.#rulePlan.prepareNightPipelineLifecycle.bind(this.#rulePlan)
      : prepareNightPipelineLifecycle;
    const lifecycle = prepare(
      {
        get world() { return pipeline.world; },
        get events() { return pipeline.events; },
        get random() { return pipeline.random; },
      },
      config,
      day,
      () => options.lifecycleHandoff,
    );
    config = lifecycle.config;
    const rulePlan = this.#rulePlan ??= RulePlan.compile(lifecycle.parameters);
    const {
      ownsWedding, ownsDemon, ownsNoble, ownsFragrant, ownsAnimal, ownsRadiant, ownsMist,
      animalNight, fragrantNight, nobleNight, radiantNight, mistNight,
      weddingNight,
    } = lifecycle;
    try {
      lifecycle.open(isCurrent);
      // 归属保持本次生命周期的原值；World／config只在每个具体检查点晚读，不缓存玩家名单。
      const readability = {
        world: () => this.world,
        config: () => config,
        ownsAnimal: () => ownsAnimal,
        ownsFragrant: () => ownsFragrant,
        ownsNoble: () => ownsNoble,
        ownsRadiant: () => ownsRadiant,
        ownsMist: () => ownsMist,
        ownsDemon: () => ownsDemon,
      };
      const assertReadable = () => assertNightReadable(readability);
      assertReadable();
      const nativeProvider =
        ownsAnimal ||
        ownsRadiant ||
        ownsMist ||
        ownsDemon ||
        isEvilKnightBoard(this.world) ||
        isNightmareBoard(this.world) ||
        config.magician !== undefined ||
        config.scholarMentor !== undefined
          ? {
              getAction: async (request: ActionRequest) => {
                assertReadable();
                const action = await actionProvider.getAction(request);
                assertReadable();
                return action;
              },
            }
          : actionProvider;
      if (ownsWedding) weddingNight.open(day, isCurrent);
      // 保原同步检查点：若有婚约，已完成原开夜；起始记录和阶段状态尚未建立，拒绝仍走原 finally。
      assertNightCommitAdmission({ world: () => this.world, day: () => day });
      safeRecordLogicOp({
        scope: "phase_pipeline",
        op: "night_pipeline_start",
        phase: Phase.Night,
        status: "ok",
        input: {
          board_size: config.boardSize,
        },
      });

      // 摄梦关系由本族按此对象身份首次使用时建立；通用状态不保存私有数组或其镜像。
      const stageState: NightStageState = {
        wolfChatOrder: [],
        endedWolves: new Set<EntityId>(),
        wolfVotes: {},
        wolfTarget: null,
        seerChecks: [],
        poisonClaims: [],
        guardClaims: [],
        merchantBacklashes: [],
        blackMarketBacklashes: [],
        mechanicalEffects: { shields: [], attacks: [], failures: [] },
        awakenedEffects: { shields: [], attacks: [] },
      };

      const requests = new GameActionRequestFactory(this.world, this.events, day);
      const stageCtx: NightStageContext = {
        isCurrent,
        previousExile: options.previousExile ? structuredClone(options.previousExile) : null,
        world: this.world,
        get nightActors() {
          return bindNightAbilityActorQuery(this.world);
        },
        get nativeNightFailure() {
          return rulePlan.nativeNightFailure(() => this.world);
        },
        get nativeNightTargets() {
          return rulePlan.nativeNightTargets(() => this);
        },
        get nativeNightEffects() {
          return rulePlan.nativeNightEffects(() => this);
        },
        roleCatalog: this.stageRegistry.roleCatalog,
        toolGateway: this.toolGateway,
        events: this.events,
        actionProvider: nativeProvider,
        currentDay: () => day,
        // 只提供晚类读取；机制仍在各自原 new 点使用原 World／events／day 参数。
        get requestFactory() { return GameActionRequestFactory; },
        makeRequest: (
          actorId: EntityId,
          allowedTools: ActionRequest["allowedTools"],
          context: ActionRequestExtras & { stage: ActionStage; requiresAction?: boolean },
        ) => this.makeRequest(requests, actorId, allowedTools, context),
        getAliveByRole: (role: Role) => this.getAliveByRole(role),
        ensureMarks: (entityId: EntityId) => this.ensureMarks(entityId),
        pickMajorityTarget: (votes: Record<number, number>) =>
          this.pickMajorityTarget(votes, config.tieBreaker?.wolfKillVote ?? "min_id"),
        pickMistKnife: (ids: readonly EntityId[]) =>
          ids.length
            ? ids[Math.floor(this.random.fork(`day:${day}:mist-knife`).next() * ids.length)]!
            : null,
        shuffleWolves: (ids: EntityId[]) =>
          shuffled(ids, this.random.fork(`day:${day}:wolf-order`)),
        state: stageState,
      };

      // 同一运行输入只持延迟表达式；各检查点按原次序读取 World／state、婚约归属和日期。
      const knifeAdmission = {
        world: () => this.world,
        state: () => stageState,
        ownsWedding: () => ownsWedding,
        day: () => day,
      };

      for (const entry of rulePlan.nightPlan(this.stageRegistry, () => this.world).entries) {
        const stage = entry.handler;
        assertEvilKnightRosterCurrent(this.world);
        if (!isCurrent())
          return attachNightUnit(attachNobleNightReceiver({ interrupted: true }, nobleNight.receiver), lifecycle.nightUnit);
        assertReadable();
        discardStaleNightKnives(knifeAdmission);
        assertNightModifierBonusEffects({ config: () => config, stageContext: () => stageCtx });
        await stage.execute(stageCtx);
        assertNightModifierBonusEffects({ config: () => config, stageContext: () => stageCtx });
        assertEvilKnightRosterCurrent(this.world);
        assertReadable();
        if (!isCurrent())
          return attachNightUnit(attachNobleNightReceiver({ interrupted: true }, nobleNight.receiver), lifecycle.nightUnit);
        discardStaleNightKnives(knifeAdmission);
      }

      discardStaleNightKnives(knifeAdmission);
      const { demonSources, demonWolfSourceCurrent, demonKnifeProtection } = prepareNightSourceDelivery({
        ownsDemon: () => ownsDemon,
        world: () => this.world,
        day: () => day,
        claims: () => stageState,
      });
      const { dreamFrame, damage } = composeNightDamage({
        ownsRadiant: () => ownsRadiant,
        world: () => this.world,
        day: () => day,
        claims: () => stageState,
        config: () => config,
        stageContext: () => stageCtx,
        solver: () => this.damageResolutionSystem,
        aliveByRole: (role) => this.getAliveByRole(role()),
      });
      if (ownsNoble) {
        const payload = {
          policy: "awa_noble_secret_body_v1" as const,
          actorId: checkpointNobleBodyAuthority(this.world, false).bodyId,
          day,
        };
        this.events.push({
          timestamp: Date.now(),
          type: "noble_body_native_damage_committed",
          payload,
          audience: Object.freeze([]),
        });
        getSessionRecorder()?.recordRequiredLogicOp({
          scope: "resolution",
          op: "noble_body_native_damage_committed",
          phase: Phase.Night,
          status: "ok",
          output: payload,
        });
      }
      assertReadable();
      for (const reflection of damage.poisonReflections ?? [])
        this.events.push({
          timestamp: Date.now(),
          type: "mechanical_poison_reflected",
          payload: { ...reflection, day },
        });
      const mist = ownsMist
        ? mistNight.captureDamage(this.world, day, stageState.wolfTarget)
        : null;
      if (mist?.extra && livingNightLife(this.world, mist.extra)) {
        const id = mist.extra.id;
        if (!damage.deaths.includes(id)) damage.deaths.push(id);
        damage.deathSources[id] = [
          ...new Set([...(damage.deathSources[id] ?? []), DeathCause.RavenClawKnife]),
        ];
      }
      if (!mist?.delayEligible) dreamFrame.expandInitialDamage(this.world, damage);
      if (!mist?.delayEligible && !ownsNoble)
        safeRecordLogicOp({
          scope: "resolution",
          op: "night_damage_resolved",
          phase: Phase.Night,
          status: "ok",
          output: {
            deaths: damage.deaths,
            death_sources: damage.deathSources,
          },
        });

      const summary: NightSummary = {
        wolfTarget: stageState.wolfTarget,
        deaths: [...damage.deaths],
        seerChecks: stageState.seerChecks,
        interruptedBySelfDestruct: false,
      };

      const deathLives = ownsDemon
        ? originalDemonNightLives(this.world)
        : new Map(
            (mist?.delayEligible ? this.world.getAliveEntityIds() : damage.deaths).map((id) => {
              const life = this.world.getComponent(id, COMPONENT.Alive)!;
              return [id, { life, version: aliveLifeVersion(life) }] as const;
            }),
          );
      lifecycle.finishPipeline();
      return attachNightUnit(attachNobleNightReceiver(
        {
          interrupted: false,
          summary,
          damage,
          dreamFrame,
          ...(mist ? { mistDelay: mist.delayEligible } : {}),
          deathLives,
          retaliationAttacks: stageState.retaliationAttacks,
          blocksPassiveNightShot: captureEvilKnightNightShotProtection(stageState),
          inspectionAttacks: stageState.inspectionAttacks,
          foxInspections: stageState.foxInspections,
          ...(demonSources ? { demonSources, demonWolfSourceCurrent, demonKnifeProtection } : {}),
        },
        nobleNight.receiver,
      ), lifecycle.nightUnit);
    } finally {
      lifecycle.abortPipeline();
    }
  }

  private makeRequest(
    requests: GameActionRequestFactory,
    actorId: EntityId,
    allowedTools: ActionRequest["allowedTools"],
    context: ActionRequestExtras & { stage: ActionStage; requiresAction?: boolean },
  ): ActionRequest {
    const { stage, requiresAction = true, ...extraContext } = context;
    return requests.create({
      phase: Phase.Night,
      actorId,
      allowedTools,
      stage,
      requiresAction,
      summary: { key: "request.summary.night_action" },
      context: {
        ...extraContext,
        ...(isMistRavenBoard(this.world) &&
        (allowedTools.includes("kill_vote") || allowedTools.includes("speak_to_wolves"))
          ? { wolf_kill_candidates: mistKnifeTargets(this.world) ?? this.world.getAliveEntityIds() }
          : {}),
        ...((isFragrantPairBoard(this.world) &&
          (allowedTools.includes("kill_vote") || allowedTools.includes("speak_to_wolves"))) ||
        isNobleBodyBoard(this.world) ||
        isRadiantEclipseBoard(this.world) ||
        isMistRavenBoard(this.world) ||
        isScholarMentorBoard(this.world) ||
        isTimeConsortBoard(this.world) ||
        isMagicianBoard(this.world) ||
        isEvilKnightBoard(this.world) ||
        isNightmareBoard(this.world) ||
        isRedMoonBoard(this.world)
          ? { action_failure_policy: "error" as const, allow_fallback: false }
          : {}),
      },
    });
  }

  /**
   * 获取指定角色的存活玩家列表。
   */
  private getAliveByRole(role: Role): EntityId[] {
    return this.world.getAliveEntityIds().filter((id) => {
      const roleComp = this.world.getComponent(id, COMPONENT.Role);
      return roleComp?.role === role;
    });
  }

  /**
   * 获取或创建目标玩家的状态印记组件。
   */
  private ensureMarks(entityId: EntityId): StatusMarksComponent {
    let marks = this.world.getComponent(entityId, COMPONENT.StatusMarks);
    if (!marks) {
      // 标记组件按需创建，避免无状态玩家占用冗余存储。
      marks = new StatusMarksComponent();
      this.world.addComponent(entityId, COMPONENT.StatusMarks, marks);
    }
    return marks;
  }

  /**
   * 依据票数选出狼刀目标，平票按编号最小值决议。
   */
  private pickMajorityTarget(
    votes: Record<number, number>,
    strategy: TieBreakerStrategy,
  ): EntityId | null {
    const entries = Object.entries(votes);
    if (entries.length === 0) {
      return null;
    }
    entries.sort((a, b) => {
      const voteDiff = b[1] - a[1];
      if (voteDiff !== 0) {
        return voteDiff;
      }
      return Number(a[0]) - Number(b[0]);
    });
    if (entries.length >= 2 && entries[0][1] === entries[1][1]) {
      if (strategy === "no_kill") {
        return null;
      }
    }
    return Number(entries[0][0]);
  }
}

/**
 * 负责普通预言家对捕获能力及目标权威的查验请求。
 * 输入为原夜上下文和校验行动；输出保留查验结果、状态、use 和事件效果。
 * 资格枚举走只读查询，具体 Seer 状态与公共 use 命令在原 commit 位置执行；映射与咒狐顺序不变。
 * Demon 封存原生控制器保持独立，不额外验证租约、退款或将原体信息写入玩家知识。
 */
import { SEER_STATE_SLOT } from "./ports";
/** 文件说明：预言家夜间查验阶段处理。 */
import { seerTargetAllowed } from "./ports";
import { COMPONENT } from "../../../../core/domain/components/names";
import { RoleComponent } from "../../../../core/domain/components/role";
import { Camp, Phase, Role } from "../../../../core/domain/model";
import { NightStageHandler } from "../../stages/night/contracts";
import { getSeerState } from "./ports";
import { resolveInspection } from "../inspection";
import { activeNightAbility } from "../abilities";
import { recordNightAbilityUse } from "../abilities";
import { captureNightAbilityScope } from "../ability_scope";
import { captureNightLife, livingNightLife } from "../../../../core/domain/night_effects";
import { recordOwnNightAction, luckyTargetAllowed } from "../night_action_history";

import { captureInspectionIdentity, commitFoxInspection } from "../cursed_fox/inspection-ports";

const seerCheckStage: NightStageHandler = {
  id: "seer_check",
  priority: 600,
  async execute(ctx): Promise<void> {
    if (ctx.nativeNightFailure.usesDemonController()) {
      const { executeDemonNativeNight } = await ctx.nativeNightEffects.loadSealedNightController();
      await executeDemonNativeNight(ctx, "seer_check");
      return;
    }
    for (const { actorId: seerId, ability } of ctx.nightActors.actors(
      "seer_check",
      ctx.currentDay(),
    )) {
      if (ability.activation === "lucky" || ability.activation === "black_market") continue;
      ctx.nativeNightFailure.assertSeerSource(ability);
      ctx.nativeNightFailure.assertNativeActor(seerId, Role.Seer);
      const day = ctx.currentDay(),
        scope = captureNightAbilityScope(
          ctx.world,
          seerId,
          ability,
          day,
          () => ctx.isCurrent() && ctx.currentDay() === day,
        );
      if (!scope?.isEligible()) continue;
      const targets = new Map(
        ctx.world.getAliveEntityIds().map((id) => [id, captureNightLife(ctx.world, id)]),
      );
      const identities = new Map(
        [...targets].flatMap(([id, life]) =>
          life ? [[id, captureInspectionIdentity(ctx.world, life)] as const] : [],
        ),
      );
      if (
        !ctx.world.getAliveEntityIds().includes(seerId) ||
        activeNightAbility(
          ctx.world.getComponent(seerId, COMPONENT.Role),
          "seer_check",
          ctx.currentDay(),
          ability.id,
        ) !== ability
      )
        continue;
      const legalTargets = ctx.world
        .getAliveEntityIds()
        .filter(
          (id) =>
            seerTargetAllowed(ability.state, seerId, id) &&
            luckyTargetAllowed(ctx.world, seerId, ability, day, "check", id),
        );
      if (!legalTargets.length) continue;
      const req = ctx.makeRequest(seerId, ["check_identity"], {
        stage: "seer",
        ability_id: ability.id,
        requiresAction: ability.state.actionPolicy !== "awa_optional_v1",
      });
      if (!scope.isEligible()) {
        ctx.nativeNightFailure.scopeStale("seer");
        continue;
      }
      const action = await ctx.actionProvider.getAction(req);
      if (!ctx.isCurrent()) return;
      if (!scope.isEligible()) {
        ctx.nativeNightFailure.scopeStale("seer");
        continue;
      }
      if (action?.name !== "check_identity") {
        ctx.nativeNightFailure.actionMissing("seer");
        continue;
      }

      const result = ctx.toolGateway.validateAndSanitize(ctx.world, seerId, action, {
        phase: Phase.Night,
        day: ctx.currentDay(),
        abilityId: ability.id,
      });
      if (!ctx.isCurrent()) return;
      if (!scope.isEligible()) {
        ctx.nativeNightFailure.scopeStale("seer");
        continue;
      }
      if (!result.ok || !result.sanitizedCall) {
        ctx.nativeNightFailure.actionInvalid("seer");
        continue;
      }

      const targetId = result.sanitizedCall.args.target_id;
      const target = targets.get(targetId);
      if (!target || !livingNightLife(ctx.world, target) || !identities.get(targetId)?.isCurrent())
        continue;
      const mapping = ctx.nativeNightTargets.mappedTarget(
        () => day,
        () => targetId,
      );
      const receipt = ctx.nativeNightTargets.reflectedTarget(
        () => day,
        () => seerId,
        () => targetId,
        "check",
      );
      if (receipt && (ability.source.kind !== "native" || ability.source.role !== Role.Seer))
        throw new Error("time_consort_seer_source_invalid");
      const effectiveId = receipt?.effectiveId ?? mapping?.effectiveId ?? targetId;
      const effectiveIdentity = identities.get(effectiveId);
      if (mapping && (!mapping.isCurrent() || !effectiveIdentity?.isCurrent()))
        throw new Error("magician_inspection_target_stale");
      const inspection = resolveInspection(ctx.world, effectiveId, "camp", ctx.roleCatalog);
      if (!ctx.isCurrent()) return;
      if (
        !scope.isEligible() ||
        !identities.get(targetId)?.isCurrent() ||
        !livingNightLife(ctx.world, target) ||
        !seerTargetAllowed(ability.state, seerId, targetId) ||
        !luckyTargetAllowed(ctx.world, seerId, ability, day, "check", targetId)
      )
        continue;
      if (mapping && (!mapping.isCurrent() || !effectiveIdentity?.isCurrent()))
        throw new Error("magician_inspection_target_stale");
      if (!inspection) continue;
      const isWerewolf = inspection.camp === Camp.Wolf;
      const seerRole = ctx.world.getComponent(seerId, COMPONENT.Role);
      if (!activeNightAbility(seerRole, "seer_check", ctx.currentDay(), ability.id)) continue;
      const seerState = seerRole ? getSeerState(seerRole, ability.id) : undefined;
      if (receipt && (!receipt.isCurrent() || !effectiveIdentity?.isCurrent()))
        throw new Error("time_consort_inspection_target_stale");
      ctx.nativeNightEffects.commitReflectedTarget(receipt, day, seerId, "check");
      if (seerState) {
        SEER_STATE_SLOT.allowedWrites.recordSeerInspection(seerState, targetId, isWerewolf, inspection);
      }

      // 原状态写入后才追加咒狐提案；仍传请求目标的原 life，随后 checks／use／效果与事实的失败不撤回此前前缀。
      commitFoxInspection(ctx.world, ctx.state, target, day, () => scope.isOwnerCurrent(true));
      ctx.state.seerChecks.push({ seerId, targetId, isWerewolf, result: { ...inspection } });
      recordNightAbilityUse(ability, ctx.currentDay(), true);
      ctx.nativeNightEffects.recordModifierTarget(day, seerId, "check", () => targetId);
      ctx.nativeNightEffects.commitNativeReflection(
        "seer_check",
        ability,
        targetId,
        () => scope.life,
        () => scope.isOwnerCurrent() && !ability.disabled && !ability.deathExpired,
      );
      recordOwnNightAction(ctx.world, seerId, day, "check", targetId, false);
      ctx.events.push({
        timestamp: Date.now(),
        type: "seer_checked",
        payload: {
          actorId: seerId,
          ...(ability.source.kind === "native" ? {} : { abilityId: ability.id }),
          targetId,
          isWerewolf,
          result: { ...inspection },
        },
      });
    }
  },
};

/** 预言家夜间阶段列表。 */
export const SEER_NIGHT_STAGES: NightStageHandler[] = [seerCheckStage];

/**
 * 负责预言家原生／受赠查验状态的创建、同实例读取与实际报告写入。输入为原角色、
 * 捕获状态及已验证目标／阵营结果；输出保留 lastTarget、lastIsWerewolf、lastResult 与历史
 * 的原有序写入。普通查验消费捕获 state，受赠查验分别读取四次 ability.state 和两次 target.id，
 * 不能缓存或合并为一次写入。JSON 复制不新增 payload 形状校验，native 库存安装归 prepared owner；
 * 目标、次数、生命与请求资格仍归原 caller／lease，政策身份字节不替代档案编码或新授权。
 */
import type { SeerState, SeerReadState } from "@ai-werewolf-arena/game-contract";

import type { EntityId, InspectionResult } from "@ai-werewolf-arena/game-contract";
import type { RoleComponent } from "../../../../core/domain/components/role";
import { copyAbilityData, findNightAbility, type NightAbilityReadView } from "../abilities";
import { commitPreparedNativeAbility } from "../abilities";

/** 安装保留原输入复制与返回 owned 引用；只在初始化入口写原生库存。 */
export function setSeerState(roleComp: RoleComponent, state: SeerState): SeerReadState {
  return commitPreparedNativeAbility(roleComp, "seer_check", SEER_STATE_SLOT.create(state));
}

/** 原生优先选择不按活跃／耗尽过滤；读取不创建或补充资源。 */
export function getSeerState(
  roleComp: RoleComponent,
  abilityId?: string,
): SeerReadState | undefined {
  return findNightAbility(roleComp, "seer_check", abilityId)?.state;
}

/** caller 仍拥有目标／scope 检查及写前、写后的效果；部分失败不回滚前缀。 */
export function recordSeerInspection(
  state: SeerReadState,
  targetId: EntityId,
  isWerewolf: boolean,
  inspection: InspectionResult,
): void {
  (state as SeerState).lastTarget = targetId;
  (state as SeerState).lastIsWerewolf = isWerewolf;
  (state as SeerState).lastResult = { ...inspection };
  (state as SeerState).history.push({ targetId, isWerewolf, result: { ...inspection } });
}

/** 受赠查验保留每次写入前的 state 读取，以及原两次 target.id 读取，不缓存它们。 */
export function recordRecipientSeerInspection(
  ability: NightAbilityReadView<"seer_check">,
  target: { readonly id: EntityId },
  isWerewolf: boolean,
  result: InspectionResult,
): void {
  (ability.state as SeerState).lastTarget = target.id;
  (ability.state as SeerState).lastIsWerewolf = isWerewolf;
  (ability.state as SeerState).lastResult = { ...result };
  (ability.state as SeerState).history.push({
    targetId: target.id,
    isWerewolf,
    result: { ...result },
  });
}

/** 原 JSON callee 先于全部状态字段读取；只迁政策身份字节，不新增 payload snapshot 或失效租约。 */
function encodePolicyIdentity(ability: NightAbilityReadView<"seer_check">): string {
  return JSON.stringify([ability.state.targetPolicy, ability.state.actionPolicy]);
}

/**
 * 本族完整契约引用原 JSON 复制函数和具体有序写入；create／schema 不改变旧接受集合。
 * install／get 与 caller 都消费同一实例库存，metadata 和 lease 保留唯一原所有者。
 * policyIdentity 是旧失效身份字节；checkpoint 归档并不调用新验证或改变原 privateState 形状。
 */
export const SEER_STATE_SLOT = Object.freeze({
  create: copyAbilityData<SeerState>,
  schema: copyAbilityData<SeerState>,
  install: setSeerState,
  get: getSeerState,
  allowedWrites: Object.freeze({
    recordSeerInspection,
    recordRecipientSeerInspection,
  }),
  checkpoint: Object.freeze({ policyIdentity: encodePolicyIdentity }),
  invalidations: Object.freeze({ policyIdentity: encodePolicyIdentity }),
});

/**
 * 负责预言家公开的终身查验去重与自身目标查询，供提示、预检和阶段重查调用。
 * 输入是只读预言家状态及行动者、目标序号；输出保留原历史去重和自身目标规则。
 * 每次查询之前，原字段读取失败继续传播；权限与失败、关闭窗口由既有租约所有者负责。
 * 公开 getter 返回同一深只读状态引用；初始化具名绑定保留原输入复制契约。
 * 本入口的初始化 setter 仅安装原生库存；普通查询不重置回合、不捕获行动权限或提交查验。
 */

import type { SeerReadState } from "@ai-werewolf-arena/game-contract";

export { getSeerState } from "./state-slot";

export function seerTargetAllowed(
  state: SeerReadState | undefined,
  actorId: number,
  targetId: number,
): boolean {
  return (
    state?.targetPolicy !== "awa_fresh_others_v1" ||
    (targetId !== actorId && !state.history.some((row) => row.targetId === targetId))
  );
}

export { setSeerState } from "./state-slot";

export { SEER_STATE_SLOT } from "./state-slot";

export { recordSeerInspection, recordRecipientSeerInspection } from "./state-slot";

/**
 * 捕获原角色、生命、状态、来源及政策身份的夜能力 owner。输入为已选择实例与阶段当前性
 * 回调；输出为原体当前性和行动资格检查。替换原槽或政策仍撤销 scope，不写状态或付款。
 * 阵营仅捕获晚取的当前值，同值组件替换不加引用撤权，缺失值仍按原值比较。
 * isOwnerCurrent 保原已付效果复验，不因运行授权墓碑失效；仅 isEligible 在原复验后拒绝退休演员。
 * 查验政策身份字节由该状态族的唯一 codec 在原表达式位置生成，生命、id、来源及允许
 * 首次死亡的版本判断仍只在此 owner，不因 payload 合法而重新授权。
 */
import type { NightAbilityKind } from "@ai-werewolf-arena/game-contract";

import { captureRadiantTurn } from "./radiant_eclipse/night_frame";
import { isRoleExecutionRetired } from "../../../core/domain/role-execution-authority";
import { COMPONENT } from "../../../core/domain/components/names";

import { captureNightLife, livingNightLife } from "../../../core/domain/night_effects";
import type { World } from "../../../core/domain/world";
import type { EntityId } from "../../../core/domain/model";
import { activeNightAbility, type NightAbilityReadView } from "./abilities";
import { aliveLifeVersion } from "../../../core/domain/components/alive";

import { DREAMER_STATE_SLOT } from "./dreamer/ports";
import { SHELTER_STATE_SLOT } from "./radiant_eclipse/shelter-state-slot";
import { SEER_STATE_SLOT } from "./seer/ports";
import { GUARD_STATE_SLOT } from "./guard/ports";
import { WITCH_STATE_SLOT } from "./witch/ports";
import { ROLE_INSPECTION_STATE_SLOT } from "./role_inspection/ports";

/** 即使库存对象仍同一引用，政策编辑也会改变授权身份。 */
function policyIdentity(ability: NightAbilityReadView): string {
  switch (ability.kind) {
    case "pair_check":
      return JSON.stringify([ability.state.policy]);
    case "shelter":
      return SHELTER_STATE_SLOT.invalidations.policyIdentity(ability);
    case "seer_check":
      return SEER_STATE_SLOT.invalidations.policyIdentity(ability);
    case "potion":
      return WITCH_STATE_SLOT.invalidations.policyIdentity(ability);
    case "guard":
      return GUARD_STATE_SLOT.invalidations.policyIdentity(ability);
    case "role_check":
      return ROLE_INSPECTION_STATE_SLOT.checkpoint.policyIdentity(ability);
    case "dream":
      return DREAMER_STATE_SLOT.invalidations.policyIdentity(ability);
  }
}

/** 请求动作前先捕获；只读资格仍在实际提交时重检，不因捕获而冻结演员。 */
export function captureNightAbilityScope<K extends NightAbilityKind>(
  world: World,
  actorId: EntityId,
  ability: NightAbilityReadView<K>,
  day: number,
  phaseCurrent: () => boolean,
) {
  const role = world.getComponent(actorId, COMPONENT.Role),
    life = captureNightLife(world, actorId);
  if (!role || !life) return null;
  const radiantCurrent = captureRadiantTurn(world, actorId, ability, day);
  const roleKind = role.role,
    camp = world.getComponent(actorId, COMPONENT.Camp)?.camp,
    privateState = role.privateState;
  const state = ability.state,
    kind = ability.kind,
    activation = ability.activation,
    id = ability.id;
  const source = ability.source,
    sourceKind = source.kind,
    sourceOwner = source.kind === "native" ? source.role : source.actorId,
    sourceId = source.kind === "copy" || source.kind === "transfer" ? source.abilityId : undefined;
  const policy = policyIdentity(ability);
  const starts = ability.startsOnDay,
    expires = ability.expiresAfterDay,
    maxUses = ability.maxUses,
    disclosed = ability.sourceDisclosed;
  const ownerCurrent = (allowFirstDeath = false) =>
    phaseCurrent() &&
    world.getComponent(actorId, COMPONENT.Role) === role &&
    role.role === roleKind &&
    world.getComponent(actorId, COMPONENT.Camp)?.camp === camp &&
    role.privateState === privateState &&
    (livingNightLife(world, life) ||
      (allowFirstDeath &&
        world.getComponent(actorId, COMPONENT.Alive) === life.life &&
        !life.life.alive &&
        aliveLifeVersion(life.life) === life.version + 1)) &&
    ability.id === id &&
    ability.kind === kind &&
    ability.activation === activation &&
    ability.state === state &&
    policyIdentity(ability) === policy &&
    (
      (role.privateState as { readonly abilities?: unknown }).abilities as
        Readonly<Record<string, NightAbilityReadView>> | undefined
    )?.[id] === ability &&
    ability.source === source &&
    source.kind === sourceKind &&
    (source.kind === "native" ? source.role : source.actorId) === sourceOwner &&
    (source.kind === "copy" || source.kind === "transfer" ? source.abilityId : undefined) ===
      sourceId &&
    ability.startsOnDay === starts &&
    ability.expiresAfterDay === expires &&
    ability.maxUses === maxUses &&
    ability.sourceDisclosed === disclosed;
  return {
    role,
    life,
    state,
    isOwnerCurrent: ownerCurrent,
    isEligible: () =>
      radiantCurrent() &&
      ownerCurrent() &&
      // 原体仍可能服务已付效果；墓碑只阻止新的行动资格，不改 ownerCurrent 或资源数据。
      !isRoleExecutionRetired(role) &&
      activeNightAbility(role, kind, day, id) === ability,
  };
}

/**
 * 负责普通夜能力唯一库存的数据复制、查询、原生安装和通用 metadata 提交。
 * 输入为原角色、捕获实例、已准备 payload 与明确日期；输出保留原字典／实例引用和能力变化事实。
 * 本 owner 写 abilities、retiredAbilityIds 及通用启停／次数／到期字段；原生 payload 准备仍归 ability_changes，
 * 授予／转移的来源与状态政策仍归 night-ability-grants，具体瓶数、梦历史、借用抑制及 Demon 审计另有原权威。
 * 字典创建、退休 ID 修订和逐字段提交保原求值顺序；发表或后续写入失败不回滚已完成前缀。
 * 数据复制不新增严格 live schema、JSON 档案接受或行动许可；readonly 视图仍是同一对象，不是冻结或第二库存。
 * F05a 只在 active／授予／转移执行入口拒永久退休身份，纯库存、状态、原生安装、已付写入与清理不据此过滤。
 */

import type {
  PairSeerState,
  NightAbilityStates,
  RoleInspectionPolicy,
  NightAbilityKind,
  AbilitySource,
  NightAbilityReadStates,
  NightAbilityReadState,
} from "@ai-werewolf-arena/game-contract";
import { readPairSeerState } from "./fragrant_pair_seer/state";
import { nativePotionSecondTurn } from "./witch/policies";
import { Role } from "../../../core/domain/model";
import type { RoleComponent } from "../../../core/domain/components/role";
import { isRoleExecutionRetired } from "../../../core/domain/role-execution-authority";
import type { RoleInitializationComponent } from "./contracts";
import { COMPONENT } from "../../../core/domain/components/names";
import type { EntityId, GameEvent } from "../../../core/domain/model";
import type { World } from "../../../core/domain/world";
import { roleOf, emit } from "./night-ability-change-runtime";
import { types as utilTypes } from "node:util";
import type {
  NightAbilityMetadata,
  AbilityStatus,
} from "@ai-werewolf-arena/game-contract/night-ability-views";
export { projectRoleInspectionState, projectSeerState, projectWitchState } from "./player_state";


export const ROLE_INSPECTION_POLICY_ROLES: Readonly<Record<RoleInspectionPolicy, Role>> = {
  gargoyle: Role.Gargoyle,
  psychic: Role.Psychic,
  mirror: Role.MirrorGirl,
  pure_white: Role.PureWhiteGirl,
  wolf_witch: Role.WolfWitch,
};


/** Pair 初始化和玩家投影共享此原纯数据校验；不读实例、World 或授予能力权限。 */
export function projectPairState(value: unknown): PairSeerState {
  const state = readPairSeerState(value);
  if (!state) throw Error("fragrant_pair_state_invalid");
  return state;
}
type NightAbilityUnion = {
  [P in NightAbilityKind]: NightAbilityMetadata & {
    kind: P;
    state: NightAbilityStates[P];
  };
}[NightAbilityKind];
export type NightAbility<K extends NightAbilityKind = NightAbilityKind> = Extract<
  NightAbilityUnion,
  { kind: K }
>;
type NightAbilityReadUnion = {
  [K in NightAbilityKind]: Readonly<
    Omit<NightAbility<K>, "state" | "source" | "nightSuppression">
  > & {
    readonly state: NightAbilityReadStates[K];
    readonly source: Readonly<AbilitySource>;
    readonly nightSuppression?: Readonly<
      import("@ai-werewolf-arena/game-contract").EclipseSuppression
    >;
  };
}[NightAbilityKind];
export type NightAbilityReadView<K extends NightAbilityKind = NightAbilityKind> = Extract<
  NightAbilityReadUnion,
  { kind: K }
>;

/** 复制有效 JSON 数据；可选 undefined 字段在落盘形状中保持缺失，不改 live 实例。 */
export function copyAbilityData<T>(value: T): T {
  const result = structuredClone(value),
    ancestors = new WeakSet<object>();
  const visit = (item: unknown): void => {
    if (item === null || typeof item === "string" || typeof item === "boolean") return;
    if (typeof item === "number" && Number.isFinite(item)) return;
    if (typeof item !== "object" || !item || ancestors.has(item))
      throw new Error("ability_state_not_json");
    ancestors.add(item);
    if (Array.isArray(item)) {
      for (let index = 0; index < item.length; index++) {
        if (!Object.hasOwn(item, index)) throw new Error("ability_state_not_json");
        visit(item[index]);
      }
    } else {
      const prototype = Object.getPrototypeOf(item);
      if (prototype !== Object.prototype && prototype !== null)
        throw new Error("ability_state_not_json");
      for (const [key, entry] of Object.entries(item)) {
        if (entry === undefined) delete (item as Record<string, unknown>)[key];
        else visit(entry);
      }
    }
    ancestors.delete(item);
  };
  visit(result);
  return result;
}

/** 资源只归该玩家实际库存中的实例，不另建并行角色状态。 */
export function allNightAbilities(role: RoleComponent | undefined): NightAbilityReadView[] {
  const stored = (role as { readonly privateState: { readonly abilities?: unknown } } | undefined)
    ?.privateState.abilities as Readonly<Record<string, NightAbilityReadView>> | undefined;
  return stored
    ? Object.values(stored).sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0))
    : [];
}

/** 检查原 nightSuppression 描述符，畸形或访问器保持 blocked，不调用该字段 getter；只读结果不授予权限／lease。 */
export function nightAbilityDisabled(ability: NightAbilityReadView): boolean {
  const blocker = Object.getOwnPropertyDescriptor(ability, "nightSuppression");
  return ability.disabled || (!!blocker && (!("value" in blocker) || blocker.value !== undefined));
}

export function abilityStatus(ability: NightAbilityReadView, day: number): AbilityStatus {
  if (nightAbilityDisabled(ability) || ability.deathExpired) return "disabled";
  if (day < ability.startsOnDay) return "pending";
  if (ability.expiresAfterDay !== undefined && day > ability.expiresAfterDay) return "expired";
  if (ability.maxUses !== null && ability.uses >= ability.maxUses) return "spent";
  if (
    ability.lastUsedDay === day &&
    !(ability.kind === "potion" && nativePotionSecondTurn(ability, day))
  )
    return "used_this_night";
  if (
    ability.kind === "potion" &&
    ability.source.kind === "native" &&
    ability.source.role === Role.Witch &&
    ability.state.potionPolicy === "awa_both_native_experimental_v1" &&
    ability.state.potionTurnClosedDay === day
  )
    return "used_this_night";
  return "active";
}

export function findNightAbility<K extends NightAbilityKind>(
  role: RoleComponent | undefined,
  kind: K,
  id?: string,
): NightAbilityReadView<K> | undefined {
  const candidates = allNightAbilities(role).filter(
    (ability): ability is NightAbilityReadView<K> => ability.kind === kind,
  );
  if (id !== undefined) return candidates.find((ability) => ability.id === id);
  // 原调用者优先选原生实例；仅有一份明确受赠实例时才采用该实例。
  return (
    candidates.find((ability) => ability.source.kind === "native") ??
    (candidates.length === 1 ? candidates[0] : undefined)
  );
}

export function activeNightAbility<K extends NightAbilityKind>(
  role: RoleComponent | undefined,
  kind: K,
  day: number,
  id?: string,
): NightAbilityReadView<K> | undefined {
  const ability = findNightAbility(role, kind, id);
  // 原数据查找／status 先完成；永久退休只否决执行，不删除库存或把状态改成 disabled。
  return ability && abilityStatus(ability, day) === "active" && role && !isRoleExecutionRetired(role)
    ? ability
    : undefined;
}

/** 读取原退休 ID 列表，不授予库存写权限。 */
export function retiredNightAbilityIds(role: RoleComponent): readonly string[] {
  return ((role.privateState as { readonly retiredAbilityIds?: unknown }).retiredAbilityIds ??
    []) as readonly string[];
}

/**
 * 原准备方已按各族规则复制并接受 payload；这里先创建字典，再读退休 ID 修订原生编号。
 * kind／来源失配时保留旧实例；匹配只替换 state，原 metadata、次数和起效日期保持。
 * 字典已创建后退休列表读取失败，不撤销这一前缀；本步不新增状态 schema 或行动许可。
 */
export function commitPreparedNativeAbility<K extends NightAbilityKind>(
  role: RoleComponent,
  kind: K,
  ownedState: NightAbilityStates[K],
): NightAbilityReadState<K>;
export function commitPreparedNativeAbility<K extends NightAbilityKind>(
  role: RoleComponent,
  kind: K,
  ownedState: NightAbilityStates[K],
  mayCommit: () => boolean,
): NightAbilityReadState<K> | null;
export function commitPreparedNativeAbility<K extends NightAbilityKind>(
  role: RoleComponent,
  kind: K,
  ownedState: NightAbilityStates[K],
  mayCommit?: () => boolean,
): NightAbilityReadState<K> | null {
  const stored = ((role.privateState as { abilities?: Record<string, NightAbility> }).abilities ??=
    {}) as Record<string, NightAbility>;
  const retired = ((role.privateState as { readonly retiredAbilityIds?: unknown })
    .retiredAbilityIds ?? []) as string[];
  const baseId = `native:${kind}`;
  let id = baseId,
    revision = 1;
  while (retired.includes(id)) id = `${baseId}:${++revision}`;
  const existing = stored[id];
  if (existing) {
    if (
      existing.kind !== kind ||
      existing.source.kind !== "native" ||
      existing.source.role !== role.role
    )
      throw new Error("ability_native_binding_conflict");
    // 已建字典与原冲突读取不回滚；回调仅否决实际 state 安装，不是完整资源许可。
    if (mayCommit && !mayCommit()) return null;
    existing.state = ownedState;
  } else {
    // 原 RHS（尤其 role.role getter）先全部完成，再核未付拒绝；不强化外来字典的接受域。
    const installed = {
      id,
      kind,
      state: ownedState,
      source: { kind: "native", role: role.role },
      sourceDisclosed: true,
      startsOnDay: 1,
      maxUses: null,
      uses: 0,
      lastUsedDay: null,
      disabled: false,
    } as NightAbility;
    if (mayCommit && !mayCommit()) return null;
    stored[id] = installed;
  }
  return ownedState as NightAbilityReadState<K>;
}

/**
 * 按原库存 ID 寻找实例；死亡到期不能重开，启停值已一致时不发布事实。
 * 先写 disabled 再发表，事件写入失败仍保留已完成的启停值，不退还具体资源。
 */
export function setNightAbilityEnabled(
  world: World,
  actorId: EntityId,
  id: string,
  enabled: boolean,
  events: GameEvent[],
): void {
  const ability = allNightAbilities(roleOf(world, actorId)).find((ability) => ability.id === id);
  if (!ability) throw new Error("ability_instance_missing");
  if (enabled && ability.deathExpired) throw new Error("ability_lucky_expired_on_death");
  if (ability.disabled === !enabled) return;
  (ability as { disabled: boolean }).disabled = !enabled;
  emit(events, actorId, ability, enabled ? "enabled" : "disabled");
}

/**
 * 退役角色已核对原体／捕获槽的借用实例，只重定义原 disabled 数据属性。
 * 目标 supplier 在 Object.defineProperty 方法查找之后执行，保原 late 字段读取位置。
 * 不按可变 id 重查、不读或执行替换的 disabled getter/setter、不删槽／退休 ID，不发布启停事实。
 * 借用租约、原主抑制和已付 payload 仍归具体 Frame；本写入不提供新行动权限或退款。
 */
export function retireBorrowedNightAbility(readBorrowed: () => NightAbilityReadView): void {
  Object.defineProperty(readBorrowed(), "disabled", {
    value: true,
    writable: true,
    enumerable: true,
    configurable: true,
  });
}

/** 实际死亡到期跟随同一实例经过转移／复活；已经付款的夜效果仍按原政策保留。 */
export function expireLuckyAbilitiesOnDeath(
  world: World,
  actorId: EntityId,
  events: GameEvent[],
): void {
  for (const ability of allNightAbilities(world.getComponent(actorId, COMPONENT.Role))) {
    if (
      (ability.activation !== "lucky" && ability.activation !== "black_market") ||
      ability.deathExpired
    )
      continue;
    (ability as { deathExpired?: boolean }).deathExpired = true;
    (ability as { disabled: boolean }).disabled = true;
    emit(events, actorId, ability, "disabled");
  }
}


/** 初始化／学习流程仍在原调用点决定起效日；这里只写原 startsOnDay，不推进业务时钟。 */
export function setNightAbilityStartDay(ability: NightAbilityReadView, day: number): void {
  (ability as { startsOnDay: number }).startsOnDay = day;
}

/** 原 status 重检后先记 lastUsedDay，再可选增加 uses；payload 库存与已付效果继续归具体机制。 */
export function recordNightAbilityUse(
  ability: NightAbilityReadView,
  day: number,
  consumed: boolean,
): void {
  if (abilityStatus(ability, day) !== "active") throw new Error("ability_not_active");
  (ability as { lastUsedDay: number | null }).lastUsedDay = day;
  if (consumed) (ability as { uses: number }).uses++;
}

/** 本族初始化已经先完成；这里只在原清空点安装新空字典，不读取退休列表或补偿旧库存。 */
export function initializeNightAbilityInventory(role: RoleInitializationComponent): void {
  role.privateState.abilities = {};
}

/** 来源与安装政策已由授予 owner 复验；安装先于发表，同一事件失败不撤回已安装实例。 */
export function commitGrantedNightAbility(
  role: RoleComponent,
  actorId: EntityId,
  ability: NightAbility,
  events: GameEvent[],
  sourceRole: RoleComponent,
): NightAbility {
  // 捕获的源／目标角色只提供本次退休读数，不新增 World 换体策略或授予许可。
  if (isRoleExecutionRetired(role) || isRoleExecutionRetired(sourceRole))
    throw new Error("ability_actor_execution_retired");
  // 原字典赋值已发生后才发布；push／时钟／来源克隆失败都保留已安装实例。
  const stored = ((role.privateState as { abilities?: Record<string, NightAbility> }).abilities ??=
    {}) as Record<string, NightAbility>;
  // 容器 getter／空字典初始化后再核；失败保原已写前缀，不安装新实例。
  if (isRoleExecutionRetired(role) || isRoleExecutionRetired(sourceRole))
    throw new Error("ability_actor_execution_retired");
  stored[ability.id] = ability;
  emit(events, actorId, ability, "granted");
  return ability;
}

/** 转移只接收稳定的自有数据槽；这不是其他 live payload 的通用 schema，也不改变授予的接受面。 */
function transferPrivateState(role: RoleComponent): object {
  if (utilTypes.isProxy(role)) throw new Error("ability_transfer_inventory_invalid");
  const descriptor = Object.getOwnPropertyDescriptor(role, "privateState");
  const value = descriptor && "value" in descriptor ? descriptor.value : undefined;
  if (!value || typeof value !== "object" || utilTypes.isProxy(value))
    throw new Error("ability_transfer_inventory_invalid");
  const prototype = Object.getPrototypeOf(value);
  if (prototype !== Object.prototype && prototype !== null)
    throw new Error("ability_transfer_inventory_invalid");
  return value;
}

/** 库存与条目保持同引用；不调用库存访问器，也不把两次 getter 相等当作稳定性证明。 */
function transferInventory(privateState: object): Record<string, NightAbility> | undefined {
  const descriptor = Object.getOwnPropertyDescriptor(privateState, "abilities");
  if (!descriptor) {
    if ("abilities" in privateState) throw new Error("ability_transfer_inventory_invalid");
    return undefined;
  }
  if (!("value" in descriptor)) throw new Error("ability_transfer_inventory_invalid");
  const value = descriptor.value;
  if (value === undefined || value === null) return undefined;
  if (typeof value !== "object" || utilTypes.isProxy(value))
    throw new Error("ability_transfer_inventory_invalid");
  const prototype = Object.getPrototypeOf(value);
  if (prototype !== Object.prototype && prototype !== null)
    throw new Error("ability_transfer_inventory_invalid");
  for (const key of Reflect.ownKeys(value)) {
    if (!("value" in Object.getOwnPropertyDescriptor(value, key)!))
      throw new Error("ability_transfer_inventory_invalid");
  }
  return value as Record<string, NightAbility>;
}

/**
 * 完整预检已完成后，唯一库存 owner 晚核原角色与真实数据槽，再按源删除／退休、目标安装、两条事实提交。
 * 同角色、同容器、同字典或源条目别名不属于合法转移输入；空目标字典仍到安装点才创建。
 * 退休列表的 getter／push 在源删除后原点执行；任何抛错保已完成前缀与原 Error，不退款、不补偿、不暗改 disabled。
 * 记录 sink 只获得事件输入，不取得库存写权；任意强制写回旧槽的 JS monkeypatch 不属于这一有界唯一 owner 保证。
 */
export function commitTransferredNightAbility(
  world: World,
  source: RoleComponent,
  originalPrivateState: object,
  target: RoleComponent,
  fromId: EntityId,
  toId: EntityId,
  id: string,
  ability: NightAbilityReadView,
  received: NightAbility,
  events: GameEvent[],
): void {
  if (source === target) throw new Error("ability_transfer_inventory_alias");
  if (roleOf(world, fromId) !== source || roleOf(world, toId) !== target)
    throw new Error("ability_transfer_owner_revoked");
  const sourcePrivate = transferPrivateState(source), targetPrivate = transferPrivateState(target);
  if (sourcePrivate !== originalPrivateState) throw new Error("ability_transfer_owner_revoked");
  if (sourcePrivate === targetPrivate) throw new Error("ability_transfer_inventory_alias");
  const sourceStored = transferInventory(sourcePrivate), targetStored = transferInventory(targetPrivate);
  if (sourceStored === targetStored && sourceStored !== undefined)
    throw new Error("ability_transfer_inventory_alias");
  if (utilTypes.isProxy(ability)) throw new Error("ability_transfer_inventory_invalid");
  const sourceEntry = sourceStored && Object.getOwnPropertyDescriptor(sourceStored, id),
    sourceId = Object.getOwnPropertyDescriptor(ability, "id");
  if (
    !sourceStored || !sourceEntry || !("value" in sourceEntry) || sourceEntry.value !== ability ||
    !sourceId || !("value" in sourceId) || sourceId.value !== id ||
    Reflect.ownKeys(sourceStored).filter(
      (key) => Object.getOwnPropertyDescriptor(sourceStored, key)!.value === ability,
    ).length !== 1
  )
    throw new Error("ability_transfer_source_slot_invalid");
  if (targetStored && Reflect.ownKeys(targetStored).some(
    (key) => Object.getOwnPropertyDescriptor(targetStored, key)!.value === ability,
  ))
    throw new Error("ability_transfer_inventory_alias");
  // 原政策与完整槽预检之后才否决退休双端；不借数据查询过滤 actor。
  if (isRoleExecutionRetired(source) || isRoleExecutionRetired(target))
    throw new Error("ability_transfer_owner_revoked");
  // 删除按已核对的真实 key，而非凭 Object.values 中的实例 id 猜测槽；失败不进入目标安装。
  delete sourceStored[id];
  (
    ((sourcePrivate as { retiredAbilityIds?: string[] }).retiredAbilityIds ??= []) as string[]
  ).push(id);
  // 源已经删除／登记 ID；期间 getter 导致角色授权退休仍拒目标安装，不补回源。
  if (isRoleExecutionRetired(source) || isRoleExecutionRetired(target))
    throw new Error("ability_transfer_owner_revoked");
  // 空目标库存的创建也在源退休之后；安装或 granted 发布失败不会重装源槽。
  const stored = targetStored ?? ((targetPrivate as { abilities?: Record<string, NightAbility> }).abilities = {});
  if (isRoleExecutionRetired(source) || isRoleExecutionRetired(target))
    throw new Error("ability_transfer_owner_revoked");
  stored[received.id] = received;
  emit(events, toId, received, "granted");
  emit(events, fromId, ability, "transferred_out");
}

/**
 * 负责死亡警长的警徽选择请求与回复复核。输入为原警徽、死者生命、阶段／日期、当前性回调及玩家／工具入口；
 * 输出为原转移或销毁结果，警徽写入仍由警徽所有者提交。请求选择和预检不提前改变警徽。
 * 死亡许可只覆盖本次选择；持有者与许可仍当前时，已选目标生命失效按原规则改为销毁。
 * 玩家异常不被伪装成一次有效选择；显式构造依赖仅在原 new 点读取，失败不补交警徽且仍关闭本次许可。
 */
import { aliveLifeVersion, type AliveComponent } from "../../../core/domain/components/alive";
import type { BadgeComponent } from "../../../core/domain/components/badge";
import type { RoleComponent } from "../../../core/domain/components/role";
import { COMPONENT } from "../../../core/domain/components/names";
import { captureNightLife, livingNightLife } from "../../../core/domain/night_effects";
import type { ActionProvider, EntityId, GameEvent, Phase } from "../../../core/domain/model";
import type { World } from "../../../core/domain/world";
import type { ActionRequestFactoryConstructorPort } from "../../../core/domain/actions";
import type { ToolGateway } from "../../gateway/tool_gateway";
import {
  badgeSuccessorEligible,
  commitSheriffBadgeChoice,
  transferOrDestroySheriffBadge,
} from "./badge";

/** 持徽死者只在引擎打开、绑定原生命版本的临时许可内选择；这不是复活后的新生命权限。 */
export async function resolveSheriffBadge(
  world: World,
  fromId: EntityId,
  reason: string,
  events: GameEvent[],
  gateway: ToolGateway,
  provider: ActionProvider,
  phase: Phase,
  day: number,
  isCurrent: () => boolean,
  construction: { readonly requestFactory: ActionRequestFactoryConstructorPort },
): Promise<void> {
  if (!isCurrent()) return;
  const badge = world.getComponent(fromId, COMPONENT.Badge);
  if (!badge?.isSheriff || badge.destroyed) return;
  if (badge.handoffPolicy !== "awa_holder_choice_v1") {
    transferOrDestroySheriffBadge(world, fromId, reason, events);
    return;
  }
  const life = world.getComponent(fromId, COMPONENT.Alive);
  const role = world.getComponent(fromId, COMPONENT.Role);
  const version = life && aliveLifeVersion(life);
  const weight = badge.voteWeight;
  // 警徽原体、政策／权重、角色与死亡生命必须仍相同；业务阶段当前性由传入回调核对。
  const current = () =>
    isCurrent() &&
    world.getComponent(fromId, COMPONENT.Badge) === badge &&
    badge.isSheriff &&
    !badge.destroyed &&
    badge.handoffPolicy === "awa_holder_choice_v1" &&
    badge.voteWeight === weight &&
    world.getComponent(fromId, COMPONENT.Role) === role &&
    world.getComponent(fromId, COMPONENT.Alive) === life &&
    life?.alive === false &&
    aliveLifeVersion(life) === version;
  if (!life || !role || !current()) return;
  const candidates = world
    .getAliveEntityIds()
    .filter((id) => badgeSuccessorEligible(world, fromId, id));
  if (!candidates.length) {
    commitSheriffBadgeChoice(world, fromId, reason, events, null);
    return;
  }
  // 固定本次候选的原生命，不能让等待期间复活的同编号替代原接收人。
  const scopes = new Map(candidates.map((id) => [id, captureNightLife(world, id)]));
  const permit = world.openDeathAction(fromId, "choose_badge_successor", phase, day, current);
  const authorized = () =>
    current() && world.hasDeathAction(fromId, "choose_badge_successor", phase, day, permit.id);
  try {
    if (!authorized()) return;
    // 许可已开启且原 authorized 通过后，才读取构造器并在原点 new；构造失败仍由 finally 关闭许可。
    const request = new construction.requestFactory(world, events, day).create({
      phase,
      actorId: fromId,
      allowedTools: ["choose_badge_successor"],
      stage: "sheriff_badge_choice",
      requiresAction: true,
      summary: { key: "request.summary.badge_choice" },
      context: {
        allow_fallback: false,
        trigger: "badge_handoff",
        death_action_id: permit.id,
        badge_candidates: candidates,
      },
    });
    if (!authorized()) return;
    const action = await provider.getAction(request);
    if (!authorized()) return;
    let target: EntityId | null = null;
    if (action?.name === "choose_badge_successor") {
      const checked = gateway.validateAndSanitize(world, fromId, action, {
        phase,
        day,
        deathActionId: permit.id,
        badgeCandidates: candidates,
      });
      if (!authorized()) return;
      if (checked.ok && checked.sanitizedCall) target = checked.sanitizedCall.args.target_id;
    }
    // 缺失／无效选择或已失效目标保留原 null 销毁政策；玩家入口抛错则直接进入 finally，不补提交。
    if (target !== null) {
      const scope = scopes.get(target);
      if (
        !scope ||
        !livingNightLife(world, scope) ||
        !badgeSuccessorEligible(world, fromId, target)
      )
        target = null;
    }
    if (authorized()) commitSheriffBadgeChoice(world, fromId, reason, events, target);
  } finally {
    permit.close();
  }
}

/**
 * 负责警徽授予、转移／销毁与票重提交。输入为原 World、警徽持有者、合格接任者及配置；
 * 输出为原警徽／VotingRight 写入和事件。先校验特殊板可读性，转移先销旧徽、重置旧票重，再安装接任状态、
 * 提交特殊 frame 和发表事实；晚失败保留此前前缀，不事务回滚或以替换组件自动恢复销毁警徽。
 */
import type { ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import { openDemonBadgeFrame, assertDemonBadgeReadable } from "../roles/demon_hunter/authority";
import { weddingBadgeSwallowed } from "../roles/ghost_bride/authority";
/** 文件说明：警徽流转、销毁与授予逻辑。 */
import { AliveComponent } from "../../../core/domain/components/alive";
import { BadgeComponent } from "../../../core/domain/components/badge";
import { COMPONENT } from "../../../core/domain/components/names";
import { VotingRightComponent } from "../../../core/domain/components/voting_right";
import { IdentityComponent } from "../../../core/domain/entities/player";
import { EntityId, GameEvent } from "../../../core/domain/model";
import { World } from "../../../core/domain/world";
import { canBeSheriff } from "../common/participation";
import type { RoleCatalog } from "../roles/catalog";

const SHERIFF_VOTE_WEIGHT = 1.5;

export interface SheriffBadgeTransferResult {
  fromId: EntityId;
  toId: EntityId | null;
  destroyed: boolean;
}

export function assignSheriff(
  world: World,
  sheriffId: EntityId,
  config?: ReadonlyBoardConfig,
  catalog?: RoleCatalog,
): boolean {
  assertDemonBadgeReadable(world);
  if (weddingBadgeSwallowed(world) || !canBeSheriff(world, sheriffId, catalog)) return false;
  const frame = openDemonBadgeFrame(world);
  const weight = config?.sheriff?.voteWeight ?? SHERIFF_VOTE_WEIGHT;
  for (const id of world.getAliveEntityIds()) {
    const badge = world.getComponent(id, COMPONENT.Badge);
    if (badge) {
      badge.isSheriff = id === sheriffId;
      badge.destroyed = false;
      badge.voteWeight = weight;
      if (config?.sheriff?.badgePolicy === "awa_holder_choice_v1")
        badge.handoffPolicy = "awa_holder_choice_v1";
      else delete badge.handoffPolicy;
    }
    const voting = world.getComponent(id, COMPONENT.VotingRight);
    if (voting?.canVote) voting.weight = id === sheriffId ? weight : 1;
  }
  frame?.commit({
    kind: "assign",
    sheriffId,
    weight,
    policy:
      config?.sheriff?.badgePolicy === "awa_holder_choice_v1" ? "awa_holder_choice_v1" : undefined,
  });
  return true;
}

export function transferOrDestroySheriffBadge(
  world: World,
  fromId: EntityId,
  reason: string,
  events: GameEvent[],
  catalog?: RoleCatalog,
): SheriffBadgeTransferResult | null {
  assertDemonBadgeReadable(world);
  const badge = world.getComponent(fromId, COMPONENT.Badge);
  if (!badge?.isSheriff || badge.destroyed) return null;
  return commitSheriffBadgeChoice(
    world,
    fromId,
    reason,
    events,
    badge.handoffPolicy === "awa_holder_choice_v1"
      ? null
      : pickNextSheriffCandidate(world, fromId, catalog),
    catalog,
  );
}

/** 只把警徽交给当前合格目标；null／拒绝目标走销毁，旧徽与票重先写，晚错误不撤回。 */
export function commitSheriffBadgeChoice(
  world: World,
  fromId: EntityId,
  reason: string,
  events: GameEvent[],
  targetId: EntityId | null,
  catalog?: RoleCatalog,
): SheriffBadgeTransferResult | null {
  assertDemonBadgeReadable(world);
  const badge = world.getComponent(fromId, COMPONENT.Badge);
  if (!badge?.isSheriff || badge.destroyed) return null;
  const frame = openDemonBadgeFrame(world);
  const weight = badge.voteWeight ?? SHERIFF_VOTE_WEIGHT;
  const policy = badge.handoffPolicy;
  const nextSheriffId =
    targetId !== null && badgeSuccessorEligible(world, fromId, targetId, catalog) ? targetId : null;
  // 旧徽先销毁并复位票重；接任安装、特殊frame提交或事件失败都保留此前前缀。
  badge.isSheriff = false;
  badge.destroyed = true;
  resetVotingWeight(world, fromId);
  if (nextSheriffId === null) {
    frame?.commit({ kind: "handoff", fromId, toId: null, weight, policy });
    events.push({
      timestamp: Date.now(),
      type: "sheriff_badge_destroyed",
      payload: { targetId: fromId, reason },
    });
    return { fromId, toId: null, destroyed: true };
  }
  const nextBadge = world.getComponent(nextSheriffId, COMPONENT.Badge);
  if (nextBadge) {
    nextBadge.isSheriff = true;
    nextBadge.destroyed = false;
    nextBadge.voteWeight = weight;
    if (policy) nextBadge.handoffPolicy = policy;
    else delete nextBadge.handoffPolicy;
  }
  const nextVoting = world.getComponent(nextSheriffId, COMPONENT.VotingRight);
  if (nextVoting) nextVoting.weight = weight;
  frame?.commit({ kind: "handoff", fromId, toId: nextSheriffId, weight, policy });
  events.push({
    timestamp: Date.now(),
    type: "sheriff_badge_transferred",
    payload: { fromId, toId: nextSheriffId, reason },
  });
  return { fromId, toId: nextSheriffId, destroyed: false };
}

function resetVotingWeight(world: World, entityId: EntityId): void {
  const voting = world.getComponent(entityId, COMPONENT.VotingRight);
  if (voting) voting.weight = voting.canVote ? 1 : 0;
}

export function badgeSuccessorEligible(
  world: World,
  fromId: EntityId,
  id: EntityId,
  catalog?: RoleCatalog,
): boolean {
  assertDemonBadgeReadable(world);
  return (
    id !== fromId &&
    canBeSheriff(world, id, catalog) &&
    world.getComponent(id, COMPONENT.Alive)?.alive === true &&
    world.getComponent(id, COMPONENT.VotingRight)?.canVote === true &&
    world.getComponent(id, COMPONENT.Badge)?.destroyed === false
  );
}

function pickNextSheriffCandidate(
  world: World,
  fromId: EntityId,
  catalog?: RoleCatalog,
): EntityId | null {
  assertDemonBadgeReadable(world);
  const candidates = world
    .getAliveEntityIds()
    .filter((id) => badgeSuccessorEligible(world, fromId, id, catalog));
  candidates.sort((a, b) => {
    const aSeat = world.getComponent(a, COMPONENT.Identity)?.seat ?? a;
    const bSeat = world.getComponent(b, COMPONENT.Identity)?.seat ?? b;
    return aSeat - bSeat;
  });
  return candidates[0] ?? null;
}

export function findSheriffId(world: World, catalog?: RoleCatalog): EntityId | null {
  assertDemonBadgeReadable(world);
  return (
    world.getAliveEntityIds().find((id) => {
      const badge = world.getComponent(id, COMPONENT.Badge);
      return (
        badge?.isSheriff === true && badge.destroyed === false && canBeSheriff(world, id, catalog)
      );
    }) ?? null
  );
}

export function assignInitialSheriff(
  world: World,
  config: ReadonlyBoardConfig,
  playerIds: EntityId[],
): void {
  if (!config.enableSheriff || config.initialSheriffSeat === undefined) return;
  const sheriffId = playerIds.find(
    (id) => world.getComponent(id, COMPONENT.Identity)?.seat === config.initialSheriffSeat,
  );
  if (sheriffId !== undefined) assignSheriff(world, sheriffId, config);
}

/**
 * 负责有序死亡波、角色死亡钩子、枪击选择、遗言与警徽交接。输入是待处理的死亡名单、
 * 原死因与原生命行动权限；输出是按原顺序提交的死亡、事件和内部关联凭证。实际生命修改和唯一已结算
 * 账本委托 DeathCommitter，双生、动物、婚约及狼美人关系事实归具体贡献；已提交整波在梦／遗言前交角色扩展，
 * 野孩子贡献自行核对榜样原生命。参数仍使用同一深只读规则视图，不建立第二份角色状态。
 * 初始和枪后追加关系准备归各自具名规则组合；本结算器仍在原逐目标时点登记来源阶段、标死并提交／发布双生回执。
 * 未提交预约只在已进入的原 finally 处取消，已提交回执不因后续发布失败而回滚。
 * 枪的资格归共同所有者，请求、等待与目标复验归规则组合；本结算器持同一许可数组并在原时点关闭。
 * 本模块不切换阶段或确定最终胜负；关系扩展、遗言、警徽和枪的最终过期保留原执行顺序。
 */
import { refreshWolfKnifeInheritanceAtCheckpoint } from "../../rulesets/wolf-knife-inheritance-plan";
import { AnimalDeathWavePreparation } from "../mechanisms/roles/animal_dream/ports";
import {
  planDeathWave,
  openDeathWave,
  deathExecutionContext,
  type DeathExecutionContext,
  deathWaveOriginalLives,
  deathWavePoisonMetadata,
